 /** Builds the request handler over a store. `clock` returns now (ms). */
 export function createApp(store, { clock = () => Date.now() } = {}) {
   return async function handle({ method = "GET", path, headers = {}, body = null }) {
     const url = new URL(path, "http://larder");
     const lang = config.defaultLanguage;
+    const now = clock();
+    let key = null;
+    let response;
+    // Routes request a save; the handler persists their changes with the audit.
+    const requestStore = Object.create(store);
+    requestStore.save = () => {};
     try {
+      const authorization = Object.entries(headers).find(([name]) => name.toLowerCase() === "authorization")?.[1];
+      const token = typeof authorization === "string" ? /^Bearer ([^\s]+)$/i.exec(authorization)?.[1] : null;
+      key = token ? store.data.apiKeys.find((entry) => entry.key === token) : null;
+      if (!key) throw new AppError("unauthorized");
+      const cookWrite = method === "POST" && (
+        /^\/recipes\/[^/]+\/cook$/.test(url.pathname) ||
+        /^\/batches\/[^/]+\/waste$/.test(url.pathname) ||
+        /^\/stocktakes\/[^/]+\/counts$/.test(url.pathname) ||
+        url.pathname === "/temperatures"
+      );
+      const allowed = key.role === "manager" || (
+        ["viewer", "cook"].includes(key.role) && url.pathname !== "/audit" &&
+        (method === "GET" || (key.role === "cook" && cookWrite))
+      );
+      if (!allowed) throw new AppError("forbidden");
       const found = match(method, url.pathname);
       if (!found) throw new AppError("not_found");
-      return await found.handler({
-        store,
+      response = await found.handler({
+        store: requestStore,
         params: found.params,
         query: Object.fromEntries(url.searchParams),
         body,
         headers,
-        now: clock(),
+        now,
       });
     } catch (e) {
-      if (e instanceof AppError) return { status: e.status, body: errorBody(e.code, t(e.code, lang, e.params)) };
-      log.error("unhandled", { message: e.message });
-      return { status: 500, body: errorBody("internal", "Something went wrong.") };
+      if (e instanceof AppError) response = { status: e.status, body: errorBody(e.code, t(e.code, lang, e.params)) };
+      else {
+        log.error("unhandled", { message: e.message });
+        response = { status: 500, body: errorBody("internal", "Something went wrong.") };
+      }
     }
+    if (method !== "GET") {
+      store.data.audit.push({ time: new Date(now).toISOString(), name: key?.name ?? null, method, path, status: response.status });
+      store.save();
+    }
+    return response;
   };
 }

